import{_ as a,o as l,c as t,a3 as i}from"./chunks/framework.DACwFHq9.js";const p=JSON.parse('{"title":"文档与来源管理","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/tools/knowledge-base/entry-management.md","filePath":"user-guide/tools/knowledge-base/entry-management.md","lastUpdated":1784331351000}'),r={name:"user-guide/tools/knowledge-base/entry-management.md"};function o(n,e,d,s,h,c){return l(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="文档与来源管理" tabindex="-1">文档与来源管理 <a class="header-anchor" href="#文档与来源管理" aria-label="Permalink to &quot;文档与来源管理&quot;">​</a></h1><p>Knowledge 的管理单元是文档，不是 CAIU 或思绪条目。每个文档保留来源路径、标题、MIME 类型、大小、checksum 和更新时间，并派生出可重建的 chunk、FTS、vector 与 graph edge。</p><h2 id="文档列表" tabindex="-1">文档列表 <a class="header-anchor" href="#文档列表" aria-label="Permalink to &quot;文档列表&quot;">​</a></h2><p>“文档”模式支持按标题和来源路径筛选。每行显示：</p><ul><li>文档标题</li><li>分块数量</li><li>文件大小</li><li>完整来源路径</li></ul><p>选择文档后，右侧会读取当前数据库中的实际分块。</p><h2 id="更新文档" tabindex="-1">更新文档 <a class="header-anchor" href="#更新文档" aria-label="Permalink to &quot;更新文档&quot;">​</a></h2><p><code>sourcePath</code> 是同一资料库内的稳定来源键。再次导入同一路径时，系统会在事务中替换文档内容和全部派生索引，避免新旧分块混用。</p><p>如果文件移动到了新路径，当前版本会把它识别为新来源。目录同步与来源重定位尚未提供产品化入口。</p><h2 id="删除文档" tabindex="-1">删除文档 <a class="header-anchor" href="#删除文档" aria-label="Permalink to &quot;删除文档&quot;">​</a></h2><p>删除需要确认。操作会同步移除：</p><ul><li>document 记录</li><li>chunk 记录</li><li>FTS 条目</li><li>chunk vector</li><li>相邻 chunk graph edge</li></ul><p>删除不可撤销，需要恢复时请重新导入源文件。</p><h2 id="重建分块索引" tabindex="-1">重建分块索引 <a class="header-anchor" href="#重建分块索引" aria-label="Permalink to &quot;重建分块索引&quot;">​</a></h2><p>资料库菜单中的“重建分块索引”会重新切分全部文档，并清除现有语义向量配置。适用于切分规则变化或索引修复。</p><p>重建完成后：</p><ul><li>关键词检索立即可用。</li><li>语义覆盖率归零。</li><li>需要再次执行“语义索引”。</li></ul><h2 id="当前不包含的能力" tabindex="-1">当前不包含的能力 <a class="header-anchor" href="#当前不包含的能力" aria-label="Permalink to &quot;当前不包含的能力&quot;">​</a></h2><p>第一阶段没有文件夹 watcher、持久化 ingest queue、文档在线编辑和来源重定位。这些能力需要和目录稳定性检查、任务恢复及失败检查器一起实现，不能仅增加一个文件监听开关。</p>',19)])])}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
